  }
  const suit = SUITS[card.suit];
  const cls = [
    'card',
    `suit-${card.suit}`,
    selected ? 'selected' : '',
    playable ? '' : 'unplayable',
    card.fused ? 'fused' : '',
  ].join(' ');
  return `<div class="${cls}" data-index="${index}" style="--suit:${suit.color};--suit-dark:${suit.dark};--suit-glow:${suit.glow}">
