.card-kind { text-align: center; font-size: 11.5px; letter-spacing: 2px; text-transform: uppercase; color: var(--suit-dark); font-weight: bold; }
.card-text { font-size: 12.5px; line-height: 1.3; text-align: center; margin-top: 6px; color: #4a3423; }
.card-power {
  position: absolute; bottom: -8px; right: -8px; width: 32px; height: 32px; border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #5a7fd6, #1e3a8a); color: #fff; font-weight: bold;
  font-size: 17px; display: flex; align-items: center; justify-content: center;
  border: 2px solid #dbeafe; box-shadow: 0 2px 6px rgba(0, 0, 0, 0.5);
}
.suit-svg { vertical-align: middle; }

.actions { display: flex; flex-direction: column; gap: 8px; flex: 0 0 150px; }
.action-btn {
  padding: 10px 12px; border-radius: 10px; font-size: 16px; font-weight: bold; color: #fff8ee;
  border: 2px solid rgba(255, 255, 255, 0.35); transition: transform 0.12s ease, filter 0.12s ease;
}
.action-btn:hover:not(:disabled) { transform: translateY(-1px); filter: brightness(1.12); }
.play-btn { background: linear-gradient(180deg, #2fa8ff, #0d63b8); }
.fuse-btn { background: linear-gradient(180deg, #ff8a3c, #c73e08); }
.end-btn { background: linear-gradient(180deg, #5a6a7a, #2a3644); }

#floaters { position: relative; }
.floater {
  position: fixed; z-index: 50; font-size: 34px; font-weight: bold; pointer-events: none;
  animation: float-up 1.4s ease-out forwards; text-shadow: 0 2px 8px rgba(0, 0, 0, 0.8);
}
.floater.damage { color: #ff5a3c; }
.floater.heal { color: #7be495; }
.floater.guard { color: #8ecbff; }
.floater.fuse { color: #ffd98a; }
.floater.draw { color: #d8b4ff; }
.floater.ai { top: 150px; left: 50%; }
.floater.player { top: 520px; left: 50%; }
@keyframes float-up {
  0% { opacity: 0; transform: translate(-50%, 10px) scale(0.8); }
  15% { opacity: 1; transform: translate(-50%, 0) scale(1.1); }
  100% { opacity: 0; transform: translate(-50%, -70px) scale(1); }
}

/* ---------- end screens ---------- */
.end-screen { text-align: center; padding-top: 70px; }
.end-screen h1 { font-size: 62px; letter-spacing: 6px; }
.end-screen.win h1 { color: #ffd98a; text-shadow: 0 0 30px rgba(255, 179, 71, 0.6); }
.end-screen.loss h1 { color: #b0a89e; text-shadow: 0 0 30px rgba(120, 120, 120, 0.4); }
.end-sub { font-size: 20px; font-style: italic; color: #e8cfae; margin: 14px 0 30px; }
.end-stats { display: flex; gap: 34px; justify-content: center; margin-bottom: 36px; }
.end-stats div { display: flex; flex-direction: column; }
.stat-num { font-size: 40px; font-weight: bold; color: #ffd98a; }
.stat-label { font-size: 14px; color: #cbb28a; letter-spacing: 1px; }
